<?php
defined('ABSPATH') || exit;

/** WordPress identities + explicit manual entitlements. No payment adapter is active. */
final class CAFCC_Access {
    public static function init(){
        add_action('admin_post_nopriv_cafcc_portal',array(__CLASS__,'handle_form'));add_action('admin_post_cafcc_portal',array(__CLASS__,'handle_form'));
        add_action('profile_update',function($uid,$old){$user=get_userdata($uid);if(!$user||$user->user_email===$old->user_email)return;global $wpdb;$t=CAFCC_Bank_DB::table('access');if($wpdb->get_var($wpdb->prepare("SELECT user_id FROM $t WHERE user_id=%d",$uid))){$wpdb->update($t,array('email_verified'=>0,'account_state'=>'pending_email','token_hash'=>'','token_expires'=>null,'updated_at'=>current_time('mysql',true)),array('user_id'=>$uid));self::event($uid,'email_changed_reverification_required');self::resend($user->user_email);}},10,2);
        add_action('rest_api_init',array(__CLASS__,'routes'));add_action('admin_menu',function(){if(CAFCC_Repository::admin_allowed())add_submenu_page('cafcc','Student access approval','Student access','manage_options','cafcc-access',array(__CLASS__,'screen'));});
        add_action('admin_enqueue_scripts',function(){if(($_GET['page']??'')==='cafcc-access'&&CAFCC_Repository::admin_allowed()){wp_enqueue_style('cafcc-studio',plugins_url('assets/studio.css',CAFCC_FILE),array(),CAFCC_VERSION);wp_enqueue_script('cafcc-access',plugins_url('assets/access-admin.js',CAFCC_FILE),array(),CAFCC_VERSION,true);wp_localize_script('cafcc-access','CAFCCAccess',array('url'=>rest_url('cafcc/v4/admin/'),'nonce'=>wp_create_nonce('wp_rest')));}});
    }
    public static function get($uid){global $wpdb;$t=CAFCC_Bank_DB::table('access');$r=$wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE user_id=%d",$uid),ARRAY_A);$r=$r?:array('user_id'=>$uid,'account_state'=>'legacy_pending','email_verified'=>0,'plan_key'=>'','entitlement_state'=>'none','starts_at'=>null,'expires_at'=>null,'updated_at'=>'');$version=hash('sha256',wp_json_encode($r));unset($r['token_hash'],$r['token_expires']);$r['version']=$version;return $r;}
    public static function eligible($uid=null){$uid=$uid??get_current_user_id();if(!$uid||!user_can($uid,'read'))return false;if(CAFCC_Repository::admin_allowed()&&$uid===get_current_user_id())return true;$r=self::get($uid);$now=current_time('mysql',true);return $r['account_state']==='approved'&&(int)$r['email_verified']===1&&$r['entitlement_state']==='active'&&$r['plan_key']!==''&&(!$r['starts_at']||$r['starts_at']<=$now)&&(!$r['expires_at']||$r['expires_at']>$now);}
    private static function event($uid,$action,$details=array()){global $wpdb;return false!==$wpdb->insert(CAFCC_Bank_DB::table('access_events'),array('user_id'=>$uid,'actor_id'=>get_current_user_id(),'event_type'=>$action,'details'=>wp_json_encode($details),'created_at'=>current_time('mysql',true)));}
    private static function rate($kind,$email=''){$ip=isset($_SERVER['REMOTE_ADDR'])?sanitize_text_field(wp_unslash($_SERVER['REMOTE_ADDR'])):'local';$keys=array('cafcc_rate_'.hash_hmac('sha256',$kind.'|'.$ip,wp_salt('nonce')));if($email)$keys[]='cafcc_rate_'.hash_hmac('sha256',$kind.'|'.strtolower($email),wp_salt('nonce'));foreach($keys as $k){$n=(int)get_transient($k);if($n>=5)return false;set_transient($k,$n+1,HOUR_IN_SECONDS);}return true;}
    public static function register($email,$password,$name){
        if(!is_string($email)||!is_email($email)||strlen($email)>190||!is_string($password)||strlen($password)<12||strlen($password)>200||!is_string($name)||!trim($name)||strlen($name)>100)return CAFCC_Repository::error('Enter your name, valid email and a password of 12–200 characters.');
        if(!self::rate('register',$email))return CAFCC_Repository::error('Please wait before trying again.',429);
        if(email_exists($email))return array('notice'=>'check_email');
        $uid=wp_insert_user(array('user_login'=>'cafcc_'.strtolower(wp_generate_password(20,false,false)),'user_pass'=>$password,'user_email'=>sanitize_email($email),'display_name'=>sanitize_text_field($name),'role'=>'subscriber'));
        if(is_wp_error($uid))return CAFCC_Repository::error('Account could not be created. Try again later.');global $wpdb;$token=bin2hex(random_bytes(32));$t=CAFCC_Bank_DB::table('access');
        if(false===$wpdb->insert($t,array('user_id'=>$uid,'account_state'=>'pending_email','email_verified'=>0,'token_hash'=>hash('sha256',$token),'token_expires'=>gmdate('Y-m-d H:i:s',time()+DAY_IN_SECONDS),'updated_at'=>current_time('mysql',true))))return CAFCC_Repository::error('Account is held for administrator assistance.',503);
        self::event($uid,'registered_pending_email');$url=add_query_arg(array('cafcc_view'=>'verify','cafcc_uid'=>$uid,'cafcc_token'=>$token),home_url('/'));
        $sent=wp_mail($email,'Verify your CA Final Command Center email',"Confirm your email using this private link, then tap Confirm Email:\n".$url."\nThis link expires in 24 hours. Verification does not grant practice access; administrator approval is required.");
        if(!$sent)self::event($uid,'verification_mail_failed');return array('notice'=>'check_email');
    }
    public static function verify($uid,$token){
        $uid=CAFCC_Repository::id($uid);if(is_wp_error($uid)||!is_string($token)||!preg_match('/^[a-f0-9]{64}$/D',$token)||!self::rate('verify'))return CAFCC_Repository::error('Verification link is invalid or expired.');
        return CAFCC_Academic::transaction(function()use($uid,$token){global $wpdb;$t=CAFCC_Bank_DB::table('access');$r=$wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE user_id=%d FOR UPDATE",$uid),ARRAY_A);if(!$r||$r['account_state']!=='pending_email'||!$r['token_hash']||!hash_equals($r['token_hash'],hash('sha256',$token))||$r['token_expires']<current_time('mysql',true))return CAFCC_Repository::error('Verification link is invalid or expired.');
            if(false===$wpdb->update($t,array('account_state'=>'pending_approval','email_verified'=>1,'token_hash'=>'','token_expires'=>null,'updated_at'=>current_time('mysql',true)),array('user_id'=>$uid))||!self::event($uid,'email_verified'))return CAFCC_Repository::error('Cannot record email verification.',500);
            wp_mail(get_option('admin_email'),'CA Final student awaiting approval','A student has verified their email and awaits manual approval. Review WordPress Admin → CA Final Command Center → Student access. User ID: '.$uid);return array('notice'=>'pending_approval');
        });
    }
    public static function resend($email){if(!is_string($email)||!is_email($email)||(!CAFCC_Repository::admin_allowed()&&!self::rate('resend',$email)))return array('notice'=>'check_email');$u=get_user_by('email',$email);if(!$u)return array('notice'=>'check_email');global $wpdb;$t=CAFCC_Bank_DB::table('access');$r=$wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE user_id=%d",$u->ID),ARRAY_A);if(!$r||$r['account_state']!=='pending_email')return array('notice'=>'check_email');$token=bin2hex(random_bytes(32));$wpdb->update($t,array('token_hash'=>hash('sha256',$token),'token_expires'=>gmdate('Y-m-d H:i:s',time()+DAY_IN_SECONDS),'updated_at'=>current_time('mysql',true)),array('user_id'=>$u->ID));$url=add_query_arg(array('cafcc_view'=>'verify','cafcc_uid'=>$u->ID,'cafcc_token'=>$token),home_url('/'));wp_mail($email,'Verify your CA Final Command Center email',"Confirm Email using this private 24-hour link:\n".$url);return array('notice'=>'check_email');}
    public static function decide($uid,$input){
        if(!CAFCC_Repository::admin_allowed())return CAFCC_Repository::error('Administrator access required.',403);$uid=CAFCC_Repository::id($uid);$user=is_wp_error($uid)?null:get_userdata($uid);if(!$user||in_array('administrator',$user->roles,true))return CAFCC_Repository::error('Choose an existing student account.');
        if(!is_array($input)||!is_string($input['notes']??'')||strlen($input['notes']??'')>10000||array_diff(array_keys($input),array('expected_version','action','plan_key','expires_at','legacy_identity_verified','notes')))return CAFCC_Repository::error('Unexpected access fields.');
        return CAFCC_Academic::transaction(function()use($uid,$input,$user){global $wpdb;$t=CAFCC_Bank_DB::table('access');$wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE user_id=%d FOR UPDATE",$uid));$r=self::get($uid);if(!is_string($input['expected_version']??null)||!hash_equals($r['version'],$input['expected_version']))return CAFCC_Repository::error('Access record changed; reload before deciding.',409);
            $action=$input['action']??'';$values=array('updated_at'=>current_time('mysql',true));
            if(in_array($action,array('approve','renew'),true)){
                $verified=(int)$r['email_verified']===1;if(!$verified&&$r['account_state']==='legacy_pending'&&true===($input['legacy_identity_verified']??false)){$verified=true;$values['email_verified']=1;}
                if(!$verified)return CAFCC_Repository::error('Email must be verified first. Existing accounts require explicit identity/email verification.');
                $plan=$input['plan_key']??'';$expires=$input['expires_at']??'';if(!is_string($plan)||!preg_match('/^[a-z0-9_-]{2,80}$/D',$plan)||!is_string($expires)||($expires&&(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$expires)||!checkdate((int)substr($expires,5,2),(int)substr($expires,8,2),(int)substr($expires,0,4))||$expires.' 23:59:59'<=current_time('mysql',true))))return CAFCC_Repository::error('Choose a plan key and future expiry date, or explicitly leave expiry blank for a manual lifetime grant.');
                $values=array_merge($values,array('account_state'=>'approved','entitlement_state'=>'active','plan_key'=>$plan,'starts_at'=>current_time('mysql',true),'expires_at'=>$expires?$expires.' 23:59:59':null));
            }elseif('request_verification'===$action){$values['account_state']='pending_email';$values['email_verified']=0;}elseif('reject'===$action){$values['account_state']='rejected';$values['entitlement_state']='none';}elseif('suspend'===$action){$values['account_state']='suspended';$values['entitlement_state']='suspended';}elseif('cancel'===$action){$values['entitlement_state']='cancelled';}else return CAFCC_Repository::error('Choose approve, renew, reject, suspend or cancel.');
            $old=$wpdb->get_var($wpdb->prepare("SELECT user_id FROM $t WHERE user_id=%d",$uid));$ok=$old?$wpdb->update($t,$values,array('user_id'=>$uid)):$wpdb->insert($t,array_merge(array('user_id'=>$uid),$values));if(false===$ok||!self::event($uid,'manual_'.$action,array('plan'=>$values['plan_key']??$r['plan_key'],'expires'=>$values['expires_at']??$r['expires_at'],'notes'=>sanitize_textarea_field($input['notes']??''),'legacy_identity_verified'=>true===($input['legacy_identity_verified']??false))))return CAFCC_Repository::error('Cannot retain audited access decision.',500);
            if($action==='request_verification'){self::resend($user->user_email);return self::get($uid);}
            wp_mail($user->user_email,'CA Final Command Center access update','Your access status has been updated: '.$action.'. Sign in to view Membership and My Account.');return self::get($uid);
        });
    }
    public static function handle_form(){
        if(!isset($_POST['_wpnonce'])||!is_string($_POST['_wpnonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['_wpnonce'])),'cafcc_portal'))wp_die('Reload the form and try again.','',array('response'=>403));
        $action=isset($_POST['portal_action'])&&is_string($_POST['portal_action'])?sanitize_key(wp_unslash($_POST['portal_action'])):'';$email=isset($_POST['email'])&&is_string($_POST['email'])?sanitize_email(wp_unslash($_POST['email'])):'';$password=isset($_POST['password'])&&is_string($_POST['password'])?wp_unslash($_POST['password']):'';$name=isset($_POST['student_name'])&&is_string($_POST['student_name'])?sanitize_text_field(wp_unslash($_POST['student_name'])):'';$notice='request_failed';$view='login';
        if('register'===$action){$r=self::register($email,$password,$name);$notice=is_wp_error($r)?'request_failed':$r['notice'];$view='pending';}
        elseif('verify'===$action){$r=self::verify($_POST['uid']??null,$_POST['token']??null);$notice=is_wp_error($r)?'invalid_link':$r['notice'];$view='pending';}
        elseif('resend'===$action){self::resend($email);$notice='check_email';$view='pending';}
        elseif('login'===$action){if(self::rate('login',$email)){$r=wp_signon(array('user_login'=>$email,'user_password'=>$password,'remember'=>false),is_ssl());if(!is_wp_error($r)){$notice='signed_in';$view=self::eligible($r->ID)?'explorer':'pending';}else $notice='login_failed';}else $notice='try_later';}
        elseif('forgot'===$action){if(self::rate('forgot',$email)){$_POST['user_login']=$email;retrieve_password($email);}$notice='reset_sent';$view='forgot';}
        $return=isset($_POST['return_to'])&&is_string($_POST['return_to'])?wp_validate_redirect(wp_unslash($_POST['return_to']),home_url('/')):home_url('/');wp_safe_redirect(add_query_arg(array('cafcc_view'=>$view,'cafcc_notice'=>$notice),$return));exit;
    }
    public static function listing($r){global $wpdb;$page=$r->get_param('page')??1;if(!is_scalar($page)||!preg_match('/^[1-9][0-9]{0,4}$/D',(string)$page))return CAFCC_Repository::error('Invalid page.');$t=CAFCC_Bank_DB::table('access');$users=$wpdb->get_results($wpdb->prepare("SELECT ID,user_email,display_name FROM $wpdb->users ORDER BY ID DESC LIMIT 50 OFFSET %d",((int)$page-1)*50),ARRAY_A);foreach($users as &$u)$u['access']=self::get((int)$u['ID']);return array('items'=>$users,'total'=>(int)$wpdb->get_var("SELECT COUNT(*) FROM $wpdb->users"),'per_page'=>50);}
    public static function routes(){
        $admin=function($r){return CAFCC_REST::permission($r,true);};register_rest_route('cafcc/v4','/admin/access',array('methods'=>'GET','permission_callback'=>$admin,'callback'=>array(__CLASS__,'listing')));register_rest_route('cafcc/v4','/admin/access/(?P<id>[1-9][0-9]{0,17})',array('methods'=>'POST','permission_callback'=>$admin,'callback'=>function($r){$d=CAFCC_Studio::body($r);return is_wp_error($d)?$d:self::decide((int)$r['id'],$d);}));
    }
    public static function screen(){if(!CAFCC_Repository::admin_allowed())wp_die('Administrator access required.');echo '<div class="wrap cafcc-studio" id="cafcc-access"><header><h1>Student access approval</h1><p>Email verification → manual approval → explicit entitlement. Existing Subscribers receive no automatic grant.</p></header><p id="access-feedback" role="status"></p><div class="studio-scroll"><table><thead><tr><th>Student</th><th>Email / account</th><th>Membership</th><th>Manual decision</th></tr></thead><tbody id="access-rows"></tbody></table></div><nav id="access-pages"></nav><p>No real payments or WooCommerce/gateway callbacks are active. Only authorised administrator actions grant access in this release.</p></div>';}
}
